import json, sys
path = sys.argv[1]
limit = int(sys.argv[2]) if len(sys.argv) > 2 else 4000
for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    if not isinstance(ev, dict):
        continue
    msg = ev.get("message") if isinstance(ev.get("message"), dict) else {}
    res = ev.get("toolUseResult") if isinstance(ev.get("toolUseResult"), dict) else {}
    ts = str(ev.get("timestamp"))[11:19]
    if isinstance(res.get("answers"), dict):
        print(f"\n--- L{n} {ts} ANSWERS: {json.dumps(res['answers'], ensure_ascii=False)[:limit]}")
        ann = res.get("annotations")
        if ann:
            print(f"    annotations: {json.dumps(ann, ensure_ascii=False)[:limit]}")
    if ev.get("type") != "user" or ev.get("isMeta"):
        continue
    content = msg.get("content")
    texts = []
    if isinstance(content, str):
        texts = [content]
    elif isinstance(content, list):
        texts = [b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text"]
    for t in texts:
        if not t.strip() or t.lstrip().startswith("<"):
            continue
        print(f"\n--- L{n} {ts} USER:\n{t[:limit]}")
EOF
