cat > "$SP/scripts/assistant.py" <<'EOF'
import json, sys
path, lo, hi = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
limit = int(sys.argv[4]) if len(sys.argv) > 4 else 6000
for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    if not (lo <= n <= hi):
        continue
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    if not isinstance(ev, dict) or ev.get("type") != "assistant":
        continue
    msg = ev.get("message") if isinstance(ev.get("message"), dict) else {}
    for b in msg.get("content") or []:
        if not isinstance(b, dict):
            continue
        if b.get("type") == "text" and b.get("text", "").strip():
            print(f"\n--- L{n} ASSISTANT TEXT:\n{b['text'][:limit]}")
        elif b.get("type") == "tool_use":
            inp = b.get("input") or {}
            if b.get("name") in ("Write", "Edit"):
                print(f"\n--- L{n} {b['name']} {inp.get('file_path')} ({len(json.dumps(inp))} chars)")
            elif b.get("name") in ("AskUserQuestion",):
                print(f"\n--- L{n} ASK: {json.dumps(inp, ensure_ascii=False)[:limit]}")
EOF
