"""Prints the body of the last issue_read/issue_write result for issue 2 found in a transcript."""
import json, sys
last = None
for line in open(sys.argv[1], encoding="utf-8", errors="replace"):
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    msg = ev.get("message") if isinstance(ev, dict) and isinstance(ev.get("message"), dict) else {}
    content = msg.get("content")
    if not isinstance(content, list):
        continue
    for b in content:
        if not (isinstance(b, dict) and b.get("type") == "tool_result"):
            continue
        parts = b.get("content")
        texts = [parts] if isinstance(parts, str) else [p.get("text", "") for p in parts or [] if isinstance(p, dict)]
        for t in texts:
            try:
                data = json.loads(t)
            except ValueError:
                continue
            if isinstance(data, dict) and data.get("number") == 2 and isinstance(data.get("body"), str):
                last = data["body"]
sys.stdout.write(last if last is not None else "")
sys.exit(0 if last is not None else 1)
EOF
